def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); ids = list(feats.ids)
    n, p = X.shape
    S = np.ones((n, 1))
    labs = sorted(set(feats.stratum))
    for s in labs[1:]:
        S = np.column_stack([S, np.array([t == s for t in feats.stratum], float)])
    def ll(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            st = np.linalg.solve(H, Z.T @ (y - mu)); b += st
            if np.max(np.abs(st)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    R = np.corrcoef(X.T); R = np.nan_to_num(R)
    def M(sel): return np.column_stack([S] + [X[:, j] for j in sel]) if sel else S
    sel = []; base = ll(S)
    while len(sel) < MAX_DRIVERS:
        a = (0.1 if len(sel) == 0 else 0.15 if len(sel) == 1 else 0.01) / p
        best, bj = -1, None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            g = ll(np.column_stack([M(sel), X[:, j]])) - base
            if g > best: best, bj = g, j
        if bj is None or stats.chi2.sf(2 * best, 1) > a: break
        cl = [k for k in range(p) if abs(R[bj, k]) >= 0.6 and k not in sel and all(abs(R[k, m]) < 0.6 for m in sel)]
        if len(cl) > 1:
            lls = {k: ll(np.column_stack([M(sel), X[:, k]])) for k in cl}
            top = max(lls.values())
            cand = [k for k in cl if lls[k] >= top - 3]
            bj = max(cand, key=lambda k: np.sum(R[k, cl] ** 2))
        sel.append(bj); base = ll(M(sel))
    changed = True
    while changed and sel:
        changed = False; full = ll(M(sel))
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (full - ll(M(rest))), 1) > (0.15 if len(sel) == 2 else 0.05) / p:
                sel = rest; changed = True; break
    prods = []; base = M(sel)
    pairs = [(i, j) for i in range(p) for j in range(i, p)]
    sc = []
    Zb = base
    for (i, j) in pairs:
        v = X[:, i] * X[:, j]; v = v - Zb @ np.linalg.lstsq(Zb, v, rcond=None)[0]
        r = y - y.mean(); sc.append(abs(v @ r) / (np.sqrt(v @ v) + 1e-9))
    order = np.argsort(sc)[::-1][:15]
    res = []
    for o in order:
        i, j = pairs[o]
        mains = sorted(set(sel) | {i, j})
        Z0 = M(mains); l0 = ll(Z0); l1 = ll(np.column_stack([Z0, X[:, i] * X[:, j]]))
        pv = stats.chi2.sf(2 * (l1 - l0), 1)
        if pv < 0.01 / len(pairs): res.append((pv, i, j))
    res.sort()
    used = set()
    for pv, i, j in res[:2]:
        if i in used or j in used: continue
        prods.append((i, j)); used |= {i, j}
    drivers = list(sel)
    for i, j in prods:
        for k in (i, j):
            if k not in drivers: drivers.append(k)
    drivers = drivers[:MAX_DRIVERS]
    cols = sorted(set(sel) | {k for pr in prods for k in pr})
    return Design(drivers=tuple(ids[k] for k in drivers), columns=tuple(ids[k] for k in cols),
                  products=tuple((ids[i], ids[j]) for i, j in prods), loadings={})

